 3	void filter_init(comp_filter_t *f, float alpha, float dt) {
 4	    f->angle     = 0.0f;
 5	    f->gyro_rate = 0.0f;
 6	    f->alpha     = alpha;
 7	    f->dt        = dt;
 8	}
 9	
10	float filter_update(comp_filter_t *f, float accel_angle, float gyro_rate) {
11	    f->gyro_rate = gyro_rate;
12	    /* Tích hợp con quay và bù lại bằng góc đo từ gia tốc kế */
13	    f->angle = f->alpha * (f->angle + gyro_rate * f->dt) + (1.0f - f->alpha) * accel_angle;
14	    return f->angle;
15	}

