 3	void pid_init(pid_controller_t *pid, float kp, float ki, float kd, float integral_max, float out_max) {
 4	    pid->kp = kp;
 5	    pid->ki = ki;
 6	    pid->kd = kd;
 7	    pid->integral = 0.0f;
 8	    pid->prev_error = 0.0f;
 9	    pid->integral_max = integral_max;
10	    pid->out_max = out_max;
11	}
12	
13	float pid_calculate(pid_controller_t *pid, float setpoint, float current_val, float dt) {
14	    float error = setpoint - current_val;
15	
16	    /* Thành phần vi phân */
17	    float derivative = 0.0f;
18	    if (dt > 0.0f) {
19	        derivative = (error - pid->prev_error) / dt;
20	    }
21	    pid->prev_error = error;
22	
23	    /* Thành phần tích phân có kẹp giới hạn chống windup */
24	    pid->integral += error * dt;
25	    if (pid->integral > pid->integral_max) {
26	        pid->integral = pid->integral_max;
27	    } else if (pid->integral < -pid->integral_max) {
28	        pid->integral = -pid->integral_max;
29	    }
30	
31	    /* Tính đầu ra */
32	    float output = (pid->kp * error) + (pid->ki * pid->integral) + (pid->kd * derivative);
33	
34	    /* Kẹp giới hạn đầu ra bão hòa */
35	    if (output > pid->out_max) {
36	        output = pid->out_max;
37	    } else if (output < -pid->out_max) {
38	        output = -pid->out_max;
39	    }
40	
41	    return output;
42	}
43	
44	void pid_reset(pid_controller_t *pid) {
45	    pid->integral = 0.0f;
46	    pid->prev_error = 0.0f;
47	}

