 28	void fsm_init(void) {
 29	    /* Cấu hình chân Buzzer D10 là OUTPUT, ban đầu tắt */
 30	    BUZZER_DDR |= (1 << BUZZER_PIN);
 31	    BUZZER_PORT &= ~(1 << BUZZER_PIN);
 32	
 33	    /* Cấu hình chân Button D12 là INPUT có điện trở kéo lên PULL-UP */
