 50	void fsm_update_background(void) {
 51	    uint32_t now = timer_get_ms();
 52	
 53	    /* Tự động tắt còi phi chặn khi hết thời gian */
 54	    if (s_buzzer_off_time > 0 && now >= s_buzzer_off_time) {
 55	        BUZZER_PORT &= ~(1 << BUZZER_PIN);
 56	        s_buzzer_off_time = 0;
 57	    }
 58	
 59	    /* Đọc nút nhấn D12 chống rung phi chặn */
 60	    bool current_btn = (BUTTON_PINREG & (1 << BUTTON_PIN)) ? true : false;
 61	    if (s_prev_btn_state && !current_btn) {
 62	        /* Bắt sườn xuống nút bấm */
 63	        if (now - s_last_btn_time > 200) {
 64	            s_last_btn_time = now;
 65	            /* Xử lý bấm nút (FR-03) */
 66	            if (s_state == STATE_BALANCING || s_state == STATE_READY) {
 67	                /* Bấm nút khi đang chạy hoặc sẵn sàng -> Dừng hẳn (FR-03) */
 68	                s_state = STATE_STOPPED;
 69	                motor_stop();
 70	                pid_reset(&s_pid);
 71	                buzzer_on_ms(100);
 72	            } else if (s_state == STATE_STOPPED || s_state == STATE_FALLEN) {
 73	                /* Bấm nút khi đang dừng/ngã -> Đưa về sẵn sàng (FR-03) */
 74	                s_state = STATE_READY;
 75	                motor_stop();
 76	                pid_reset(&s_pid);
 77	                buzzer_on_ms(50);
 78	            }
 79	        }
 80	    }
 81	    s_prev_btn_state = current_btn;
 82	
 83	    /* Xử lý khởi tạo và hiệu chuẩn ở trạng thái INIT */
 84	    if (s_state == STATE_INIT) {
 85	        buzzer_on_ms(50); /* Báo hiệu đang khởi động (FR-01) */
 86	        s_state = STATE_CALIBRATING;
