#define CONTROL_PERIOD_MS    4.0f      /* Fact f-nguoi-66277026 (anh cho, chưa có tài liệu) */
#define TIMER_BASE_HZ        1000.0f   /* Fact f-nguoi-2633608 (anh cho, chưa có tài liệu) */
