    cs->motor_speed = 0;
    cs->motor_enabled = false;
    pid_reset(&cs->pid);
}

void control_set_state(control_system_t *cs, control_state_t new_state) {
    cs->state = new_state;
    if (new_state == CONTROL_STATE_READY || new_state == CONTROL_STATE_STOPPED || new_state == CONTROL_STATE_FALLEN) {
        control_reset(cs);
    }
}

