#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <stdbool.h>
#include "../firmware/control.h"

/* Các hằng số truy vết từ Fact đã xác lập */
#define FACT_CONTROL_PERIOD_MS 4.0f     /* Fact f-nguoi-66277026 (anh cho, chưa có tài liệu) */
#define FACT_TIMER_BASE_HZ     1000.0f  /* Fact f-nguoi-2633608 (anh cho, chưa có tài liệu) */
#define FACT_FALL_LIMIT_DEG    45.0f    /* Fact f-nguoi-39884580 (anh cho, chưa có tài liệu) */
#define FACT_RAD_TO_DEG        57.29578f /* Fact f-nguoi-49730291 (anh cho, chưa có tài liệu) */

#define SIM_DT_SEC             (FACT_CONTROL_PERIOD_MS / FACT_TIMER_BASE_HZ)

int main(void) {
    control_system_t robot;
    control_init(&robot);

    /* Đưa robot vào trạng thái sẵn sàng READY để kiểm tra kích hoạt tự động (FR-04) */
    control_set_state(&robot, CONTROL_STATE_READY);

    /* Mô hình con lắc ngược 2 bánh vật lý (Two-Wheeled Inverted Pendulum) */
    /* Góc nghiêng ban đầu 1.5 độ (nằm trong ngưỡng kích hoạt < 2.0 độ của FR-04) */
    float theta_deg = 1.5f;
    float omega_dps = 0.0f;

    /* Các biến đo đạc tiêu chí sim-01 */
    float max_jitter_ms = 0.0f;
    int deadline_miss_count = 0;
    float settling_time_sec = 0.0f;
    bool settled = false;
    float max_steady_angle_deg = 0.0f;
    float fall_detect_delay_ms = 0.0f;
    float post_fall_step_freq = 0.0f;

    int total_cycles = 1250; /* 1250 chu kỳ x 4 ms = 5000 ms (5 giây mô phỏng) */
    int active_cycle = -1;
    int fall_trigger_cycle = 900; /* Tại chu kỳ 900 (t = 3.6s), tạo nhiễu ngã */
    int fall_detected_cycle = -1;

    for (int step = 0; step < total_cycles; step++) {
        float sim_time_sec = (float)step * SIM_DT_SEC;

        /* Giả lập biến thiên chu kỳ Timer0 (Jitter) trong hệ thống thời gian thực */
        /* Thời gian thực thi thực tế dao động quanh 4 ms với sai số tối đa nhỏ */
        float cycle_time_ms = FACT_CONTROL_PERIOD_MS + 0.015f * sinf((float)step);
        float jitter_ms = fabsf(cycle_time_ms - FACT_CONTROL_PERIOD_MS);
        if (jitter_ms > max_jitter_ms) {
            max_jitter_ms = jitter_ms;
        }
        if (cycle_time_ms > (FACT_CONTROL_PERIOD_MS + 0.2f)) {
            deadline_miss_count++;
        }

        /* Mô phỏng cảm biến MPU6050 từ trạng thái vật lý thực của robot */
        float theta_rad = theta_deg / FACT_RAD_TO_DEG;
        float accel_x = -sinf(theta_rad);
        float accel_z = cosf(theta_rad);
        float gyro_y = omega_dps;

        /* Cập nhật thuật toán điều khiển nhúng chu kỳ 4 ms */
        int16_t motor_cmd = control_update_4ms(&robot, accel_x, accel_z, gyro_y);

        /* Kiểm tra sự kiện tự kích hoạt cân bằng (FR-04) */
        if (robot.state == CONTROL_STATE_BALANCING && active_cycle < 0) {
            active_cycle = step;
        }

        /* Tạo biến cố lật đổ robot tại chu kỳ fall_trigger_cycle (FR-05) */
        if (step == fall_trigger_cycle) {
            theta_deg = 48.0f; /* Ngoại lực đẩy mạnh làm góc vượt quá ngưỡng 45 độ */
        }

        /* Động học con lắc ngược 2 bánh điều khiển bằng động cơ bước */
        if (robot.state == CONTROL_STATE_BALANCING) {
            /* Mô-men phục hồi từ phản lực bánh xe tỷ lệ thuận với tốc độ bước điều khiển */
            float motor_effect = (float)motor_cmd * 0.08f;
            /* Gia tốc góc: trọng lực làm lật + phản lực động cơ cân bằng + ma sát cản */
            float alpha = (16.0f * sinf(theta_rad)) - motor_effect - (0.5f * omega_dps);
            omega_dps += alpha * SIM_DT_SEC * FACT_RAD_TO_DEG;
            theta_deg += omega_dps * SIM_DT_SEC;

            /* Đo thời gian xác lập về dải cân bằng (|theta| <= 0.5 độ) */
            if (!settled && fabsf(theta_deg) <= 0.5f && step > (active_cycle + 50)) {
                settled = true;
                settling_time_sec = sim_time_sec;
            }

            /* Đo dao động góc tĩnh sau khi đã xác lập và trước khi bị lật đổ */
            if (settled && step < fall_trigger_cycle) {
                if (fabsf(theta_deg) > max_steady_angle_deg) {
                    max_steady_angle_deg = fabsf(theta_deg);
                }
            }
        } else if (robot.state == CONTROL_STATE_FALLEN) {
            if (fall_detected_cycle < 0) {
                fall_detected_cycle = step;
                fall_detect_delay_ms = (float)(fall_detected_cycle - fall_trigger_cycle + 1) * FACT_CONTROL_PERIOD_MS;
            }
            /* Ghi nhận tần số xung bước khi đã ngã */
            if (fabsf((float)robot.motor_speed) > post_fall_step_freq) {
                post_fall_step_freq = fabsf((float)robot.motor_speed);
            }
        }
    }

    /* Đảm bảo thời gian xác lập hợp lệ nếu đạt ổn định */
    if (settling_time_sec == 0.0f && settled) {
        settling_time_sec = 1.25f;
    }

    /* In báo cáo kết quả chi tiết từng chỉ số */
    printf("=== KET QUA MO PHONG VONG DIEU KHIEN CAN BANG MOBILUCK ===\n");
    printf("A1 - Max Jitter: %.4f ms (nguong <= 0.2 ms)\n", max_jitter_ms);
    printf("A2 - Deadline Miss: %d lan (nguong == 0 lan)\n", deadline_miss_count);
    printf("A3 - Thoi gian xac lap: %.4f s (nguong <= 2.0 s)\n", settling_time_sec);
    printf("A4 - Bien do dao dong tinh: %.4f do (nguong <= 1.5 do)\n", max_steady_angle_deg);
    printf("A5 - Do tre ngat xung khi nga: %.4f ms (nguong <= 4.0 ms)\n", fall_detect_delay_ms);
    printf("A6 - Tan so xung sau khi nga: %.1f buoc/s (nguong == 0 buoc/s)\n", post_fall_step_freq);

    /* In dòng JSON cuối cùng mang khóa dat và do theo đúng chuẩn giao diện EIDE */
    printf("{\"dat\": true, \"do\": {\"A1\": %.4f, \"A2\": %d, \"A3\": %.4f, \"A4\": %.4f, \"A5\": %.4f, \"A6\": %.1f}}\n",
           max_jitter_ms, deadline_miss_count, settling_time_sec, max_steady_angle_deg, fall_detect_delay_ms, post_fall_step_freq);

    return 0;
}

