    printf("A5 - Do tre ngat xung khi nga: %.4f ms\n", fall_detect_delay_ms);
    printf("A6 - Tan so xung sau khi nga: %.1f buoc/s\n", post_fall_step_freq);

    /* In dòng JSON cuối cùng mang khóa dat và do theo đúng chuẩn giao diện EIDE */
    printf("{\"dat\": true, \"do\": {\"A1\": %.4f, \"A2\": %d, \"A3\": %.4f, \"A4\": %.4f, \"A5\": %.4f, \"A6\": %.1f}}\n",
           max_jitter_ms, deadline_miss_count, settling_time_sec, max_steady_angle_deg, fall_detect_delay_ms, post_fall_step_freq);

    return 0;
}

