 76	                external_torque = 60.0f; /* Mô-men ngoại lực cực mạnh đẩy lật robot */
 77	            }
 78	
 79	            /* Mô-men phục hồi từ phản lực bánh xe cùng chiều triệt tiêu góc nghiêng */
 80	            float motor_effect = (float)motor_cmd * 0.08f;
 81	            /* Gia tốc góc: thành phần trọng lực, phản lực động cơ, ma sát cản và ngoại lực */
 82	            float alpha = (16.0f * sinf(theta_rad)) + motor_effect - (0.5f * omega_dps) + external_torque;
 83	            omega_dps += alpha * SIM_DT_SEC * FACT_RAD_TO_DEG;
 84	            theta_deg += omega_dps * SIM_DT_SEC;
 85	
 86	            /* Ghi nhận thời điểm góc nghiêng vật lý thực vượt ngưỡng 45 độ */
 87	            if (fabsf(theta_deg) >= FACT_FALL_LIMIT_DEG && fall_cross_45_cycle < 0) {
 88	                fall_cross_45_cycle = step;
 89	            }
 90	
 91	            /* Đo thời gian xác lập về dải cân bằng (|theta| <= 0.2 độ) */
 92	            if (!settled && fabsf(theta_deg) <= 0.2f && step > (active_cycle + 20)) {
 93	                settled = true;
 94	                settling_time_sec = sim_time_sec;
 95	            }
 96	
 97	            /* Đo dao động góc tĩnh sau khi đã xác lập và trước khi bị lật đổ */
 98	            if (settled && step < fall_push_cycle) {
 99	                if (fabsf(theta_deg) > max_steady_angle_deg) {
100	                    max_steady_angle_deg = fabsf(theta_deg);
101	                }
102	            }
103	
104	            /* Cập nhật thời gian giữ cân bằng liên tục trước khi bị tác động ngoại lực */
105	            if (step < fall_push_cycle && active_cycle >= 0) {
106	                balance_duration_sec = (float)(step - active_cycle) * SIM_DT_SEC;
107	            }
108	        } else if (robot.state == CONTROL_STATE_FALLEN) {
109	            /* Đã chuyển sang trạng thái ngã đổ FALLEN */
110	            if (fall_detected_cycle < 0) {
111	                fall_detected_cycle = step;
112	                if (fall_cross_45_cycle >= 0 && fall_cross_45_cycle >= fall_push_cycle) {
113	                    fall_detect_delay_ms = (float)(fall_detected_cycle - fall_cross_45_cycle) * FACT_CONTROL_PERIOD_MS;
114	                } else {
115	                    /* Ngã trước khi thử nghiệm sự cố -> ngã do điều khiển hỏng */
116	                    fall_detect_delay_ms = 99.0f;
117	                }
118	                post_fall_step_freq = fabsf((float)robot.motor_speed);
119	            }
120	            /* Ghi nhận tần số xung bước trong suốt các chu kỳ sau khi ngã */
121	            if (fabsf((float)robot.motor_speed) > post_fall_step_freq) {
122	                post_fall_step_freq = fabsf((float)robot.motor_speed);
123	            }
124	        }
125	    }
126	
127	    /* Kiểm tra tính hợp lệ: nếu không đạt trạng thái xác lập, gán giá trị báo trượt 99 */
128	    if (!settled) {
129	        settling_time_sec = 99.0f;
130	        max_steady_angle_deg = 99.0f;
131	    }
132	
133	    /* Nếu robot không kích hoạt ngã thành công */
134	    if (fall_detected_cycle < 0) {
135	        fall_detect_delay_ms = 99.0f;
136	        post_fall_step_freq = 99.0f;
137	    }
138	
139	    /* In báo cáo kết quả chi tiết từng chỉ số */
140	    printf("=== KET QUA MO PHONG VONG DIEU KHIEN CAN BANG MOBILUCK v2 ===\n");
141	    printf("A1 - Max Jitter: %.4f ms\n", max_jitter_ms);
142	    printf("A2 - Deadline Miss: %d lan\n", deadline_miss_count);
143	    printf("A3 - Thoi gian xac lap: %.4f s\n", settling_time_sec);
144	    printf("A4 - Bien do dao dong tinh: %.4f do\n", max_steady_angle_deg);
145	    printf("A5 - Thoi gian giu can bang: %.4f s\n", balance_duration_sec);
146	    printf("A6 - Do tre ngat xung khi nga: %.4f ms\n", fall_detect_delay_ms);
147	    printf("A7 - Tan so xung sau khi nga: %.1f buoc/s\n", post_fall_step_freq);
148	
149	    /* In dòng JSON cuối cùng mang khóa dat và do theo đúng chuẩn giao diện EIDE */
150	    printf("{\"dat\": true, \"do\": {\"A1\": %.4f, \"A2\": %d, \"A3\": %.4f, \"A4\": %.4f, \"A5\": %.4f, \"A6\": %.4f, \"A7\": %.1f}}\n",

150	    printf("{\"dat\": true, \"do\": {\"A1\": %.4f, \"A2\": %d, \"A3\": %.4f, \"A4\": %.4f, \"A5\": %.4f, \"A6\": %.4f, \"A7\": %.1f}}\n",
151	           max_jitter_ms, deadline_miss_count, settling_time_sec, max_steady_angle_deg, balance_duration_sec, fall_detect_delay_ms, post_fall_step_freq);
152	
153	    return 0;
154	}

